import{_ as t}from"./chunks/ugso_callmebot_signal_action.BgUmPS02.js";import{_ as a,o as s,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const o="/assets/callmebot-signal/fr.png",h=JSON.parse('{"title":"CallMeBot Signal","description":"Messages texte Signal depuis Home Assistant avec profils et Blockly.","frontmatter":{"title":"CallMeBot Signal","description":"Messages texte Signal depuis Home Assistant avec profils et Blockly."},"headers":[],"relativePath":"fr/projects/callmebot-signal/index.md","filePath":"fr/projects/callmebot-signal/index.md","lastUpdated":1793128957000}'),n={name:"fr/projects/callmebot-signal/index.md"};function l(c,e,u,p,d,m){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="callmebot-signal" tabindex="-1">CallMeBot Signal <a class="header-anchor" href="#callmebot-signal" aria-label="Permalink to &quot;CallMeBot Signal&quot;">​</a></h1><p><strong>Application HA 0.1.2 bêta</strong> dans le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">dépôt commun de Blocks for HA</a>. Entièrement <strong>DE/EN/FR</strong>, langue système et apparence claire/sombre/système. Implémentation UGSo originale inspirée de <a href="https://github.com/derAlff/ioBroker.signal-cmb" target="_blank" rel="noreferrer">ioBroker.signal-cmb</a>.</p><p><img src="'+o+'" alt="Interface Signal en français"></p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ol><li>Ajouter <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> au magasin HA et installer <strong>CallMeBot Signal</strong>.</li><li>Configurer MQTT dans HA, démarrer l’application et ouvrir son interface Ingress. Les identifiants MQTT du Supervisor sont prioritaires ; les options servent de secours.</li><li>Utiliser le contact actuel du bot indiqué dans le <a href="https://www.callmebot.com/blog/free-api-signal-send-messages/" target="_blank" rel="noreferrer">guide officiel Signal</a>. Envoyer la phrase d’activation dans <strong>Signal</strong> et attendre la <strong>clé API Signal</strong>.</li><li>Enregistrer l’ID du profil, son nom, votre numéro international <strong>avec +</strong> ou <strong>UUID Signal</strong>, et la clé correspondante. Si le numéro est masqué, le bot peut fournir un UUID. Copier le destinataire du lien d’activation sans le modifier.</li><li>Choisir le profil par défaut. « Envoyer le message » envoie réellement au profil enregistré sélectionné.</li></ol><p>Les clés WhatsApp ne fonctionnent pas pour Signal. Les deux applications peuvent fonctionner ensemble : profils, sujets MQTT, identifiants clients et entités de diagnostic séparés. L’<a href="./../callmebot/">application WhatsApp</a> conserve ses identifiants techniques.</p><h2 id="blockly-et-selection-du-profil" tabindex="-1">Blockly et sélection du profil <a class="header-anchor" href="#blockly-et-selection-du-profil" aria-label="Permalink to &quot;Blockly et sélection du profil&quot;">​</a></h2><p>Depuis <strong>Blocks for HA 0.1.50</strong> : <strong>Messages → Signal · CallMeBot</strong>.</p><p><img src="'+t+'" alt="Bloc Signal"></p><p>Cliquer sur le champ du profil, rechercher par nom/ID et sélectionner. Vide utilise le destinataire par défaut. Le nom est affiché, l’ID est enregistré. Connecter du texte, une variable ou Jinja. Journal : erreurs seules, aucun ou info. Le bloc produit une action native <code>mqtt.publish</code> ; le JSON est sérialisé après l’évaluation du modèle.</p><p>L’application publie le catalogue sur <code>ugso/callmebot_signal/profiles</code> et l’entité de diagnostic MQTT <strong><code>sensor.ugso_callmebot_signal_profiles</code></strong>. État : nombre de profils. Attributs : IDs, noms, profil par défaut et marqueur source, <strong>sans destinataire, message ni clé</strong>. Blocks utilise le marqueur même si l’entité est renommée. Préfixe de découverte standard : <code>homeassistant</code>.</p><p>Sans connexion, saisir l’ID manuellement ou le laisser vide. Les IDs invalides/supprimés ne sont jamais remplacés automatiquement. Les projets JSON conservent le bloc dédié ; l’import YAML représente l’envoi par une action HA/MQTT générale.</p><h2 id="protocole-et-limites" tabindex="-1">Protocole et limites <a class="header-anchor" href="#protocole-et-limites" aria-label="Permalink to &quot;Protocole et limites&quot;">​</a></h2><ul><li>Envoi : <code>ugso/callmebot_signal/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Exemple : <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Bonjour depuis HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Un profil vide utilise le destinataire par défaut.</li><li>Résultat : <code>ugso/callmebot_signal/result</code>, non retenu, uniquement profil, ID de requête, état et heure.</li><li>Catalogue et disponibilité : <code>ugso/callmebot_signal/profiles</code> et <code>ugso/callmebot_signal/availability</code>, retenus. La disponibilité reflète la connexion au courtier.</li><li>Maximum 16 profils, 4000 caractères, file de 20 et 10 secondes entre tentatives par profil. Les commandes plus rapides sont refusées.</li><li><code>request_id</code> facultatif : déduplication pendant une heure, maximum 1000 IDs. Sans réessai automatique ni répétition après redémarrage ; commandes retenues refusées.</li><li>Une instance Signal par courtier. Limiter les droits d’écriture sur les commandes. La configuration MQTT TLS externe n’est pas incluse.</li></ul><p>Cette application envoie des <strong>textes à vos propres destinataires activés</strong>. Images, groupes et réponses ne sont pas implémentés. <code>accepted</code> confirme uniquement l’acceptation API. Destinataire, clé et message sont transmis par HTTPS à <code>https://signal.callmebot.com/signal/send.php</code>.</p><p>Les clés restent dans le fichier privé <code>/data/profiles.json</code>, ne sont jamais renvoyées au navigateur/MQTT/Blockly et ne sont pas journalisées. Ce fichier n’est pas chiffré et figure dans les sauvegardes HA ; protéger les sauvegardes.</p><h2 id="verification" tabindex="-1">Vérification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Vérification&quot;">​</a></h2><p>Backend, validation UUID/numéro, protocole MQTT, export Blockly/Jinja, DE/EN/FR et affichage mobile sont vérifiés avec des données de test. Livraison Signal réelle et installation HA Supervisor nécessitent votre propre configuration. Les tests automatisés n’envoient aucun message réel.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot_signal" target="_blank" rel="noreferrer">Code source</a> · Apache-2.0 · Projet communautaire indépendant.</p><h2 id="beta-historique-sauvegarde-des-profils-et-mqtt-tls" tabindex="-1">Bêta : historique, sauvegarde des profils et MQTT TLS <a class="header-anchor" href="#beta-historique-sauvegarde-des-profils-et-mqtt-tls" aria-label="Permalink to &quot;Bêta : historique, sauvegarde des profils et MQTT TLS&quot;">​</a></h2><p>L’historique conserve jusqu’à 200 entrées : date, ID du profil, source et résultat. Filtrer par profil/erreur et confirmer l’effacement. Sans messages, numéros, clés API ni ID de requête. Acceptée signifie acceptation par le fournisseur, pas confirmation de livraison. Une erreur de stockage ne provoque aucun renvoi automatique.</p><p>La sauvegarde chiffre les profils, numéros, clés API et destinataire par défaut avec AES-GCM et une clé dérivée du mot de passe (scrypt). Au moins 12 caractères ; conserver le mot de passe séparément. Il n’est pas enregistré. Restaurer nécessite le mot de passe, une confirmation et un contenu valide. Mot de passe incorrect, fichier altéré ou sauvegarde de l’autre application : profils inchangés. Les envois en attente bloquent la restauration. Identifiants MQTT et historique exclus ; utiliser une sauvegarde complète HA pour ceux-ci.</p><p>Le broker HA automatique reste le réglage existant. Désactiver l’automatisme pour définir un broker externe, son port et ses identifiants. TLS vérifie certificat et nom d’hôte ; import PEM de CA et certificat/clé client possible. Choisir le port TLS, souvent 8883. Champs secrets vides : valeurs enregistrées conservées. HA/Blocks doit utiliser ce broker ou transférer les topics d’envoi/résultat/profils/discovery entre brokers ; aucune passerelle automatique.</p><p>profiles.json, profils, clés, topics MQTT et ID d’entités conservés. Historique : /data/history.json ; réglages MQTT explicitement enregistrés : /data/mqtt.json. Aucune réécriture automatique lors de la mise à jour. Interface DE/EN/FR.</p><p>L’interface et la description portent Bêta. HA n’accepte pas beta comme stage natif ; experimental reste donc la valeur technique valide. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">Configuration HA</a>.</p>',25)])])}const v=a(n,[["render",l]]);export{h as __pageData,v as default};
